<?php use FilamentManager\Core\View; ?>
<div class="toolbar"><div><h1><?= View::e($location['name']) ?></h1><p class="muted"><?= View::e($location['code']?:View::t('without_code')) ?><?php if($location['parent_name']): ?> · <?= View::t('parent_location') ?>: <?= View::e($location['parent_name']) ?><?php endif; ?></p></div><a class="button secondary-button" href="<?= View::e($basePath) ?>/locations"><?= View::t('back_to_warehouse') ?></a></div>
<?php if($location['description']): ?><p class="card location-description"><?= View::e($location['description']) ?></p><?php endif; ?>
<div class="cards location-summary"><section class="card"><h2><?= View::t('all_spools') ?></h2><strong class="summary-number"><?= View::e($summary['total']) ?></strong></section><section class="card"><h2><?= View::t('available') ?></h2><strong class="summary-number summary-available"><?= View::e($summary['available']) ?></strong></section><section class="card"><h2><?= View::t('loaded_in_printers') ?></h2><strong class="summary-number"><?= View::e($summary['loaded']) ?></strong></section><section class="card"><h2><?= View::t('empty_spools') ?></h2><strong class="summary-number"><?= View::e($summary['empty']) ?></strong></section><section class="card"><h2><?= View::t('spool_capacity') ?></h2><strong class="summary-number"><?= $summary['capacity']===null?'—':View::e($summary['capacity']) ?></strong></section><section class="card"><h2><?= View::t('occupied_spaces') ?></h2><strong class="summary-number"><?= View::e($summary['occupied']) ?></strong></section><section class="card <?= $summary['full']?'location-capacity-full':'' ?>"><h2><?= View::t('free_space') ?></h2><strong class="summary-number"><?= $summary['free']===null?'—':View::e($summary['free']) ?></strong><?php if($summary['full']): ?><small class="inventory-full"><?= View::t('location_full') ?></small><?php endif; ?></section></div>
<section class="card location-section"><h2><?= View::t('material_summary') ?></h2><div class="table-wrap"><table><thead><tr><th><?= View::t('material') ?></th><th><?= View::t('manufacturer') ?></th><th><?= View::t('color') ?></th><th><?= View::t('quantity') ?></th><th><?= View::t('available') ?></th><th><?= View::t('loaded_in_printers') ?></th><th><?= View::t('total_remaining_weight') ?></th></tr></thead><tbody><?php foreach($materialGroups as $group): $hex=preg_match('/^#[0-9A-Fa-f]{6}$/',(string)$group['color_hex'])?$group['color_hex']:'#d0d5dd'; ?><tr><td><strong><?= View::e($group['material_type']) ?></strong><?php if($group['commercial_name']): ?><br><small><?= View::e($group['commercial_name']) ?></small><?php endif; ?></td><td><?= View::e($group['manufacturer_name']?:'—') ?></td><td><input class="color-swatch" type="color" value="<?= View::e($hex) ?>" disabled> <?= View::e($group['color_name']) ?></td><td><?= View::e($group['spool_count']) ?></td><td><?= View::e($group['available_count']) ?></td><td><?= View::e($group['loaded_count']) ?></td><td><?= View::e(number_format((float)$group['total_weight_g'],0,',',' ')) ?> g</td></tr><?php endforeach; ?><?php if(!$materialGroups): ?><tr><td colspan="7"><?= View::t('location_has_no_spools') ?></td></tr><?php endif; ?></tbody></table></div></section>
<section class="card location-section"><h2><?= View::t('individual_spools') ?></h2><div class="table-wrap"><table><thead><tr><th><?= View::t('material') ?></th><th><?= View::t('manufacturer') ?></th><th><?= View::t('color') ?></th><th><?= View::t('remaining') ?></th><th><?= View::t('status') ?></th><th><?= View::t('current_position') ?></th><th></th></tr></thead><tbody><?php foreach($spools as $spool): $hex=preg_match('/^#[0-9A-Fa-f]{6}$/',(string)$spool['color_hex'])?$spool['color_hex']:'#d0d5dd'; ?><tr><td><strong><?= View::e($spool['material_type']) ?></strong><?php if($spool['commercial_name']): ?><br><small><?= View::e($spool['commercial_name']) ?></small><?php endif; ?></td><td><?= View::e($spool['manufacturer_name']?:'—') ?></td><td><input class="color-swatch" type="color" value="<?= View::e($hex) ?>" disabled> <?= View::e($spool['color_name']) ?></td><td><?= View::e(number_format((float)$spool['current_net_weight_g'],0,',',' ')) ?> g</td><td><span class="inventory-status inventory-status-<?= View::e($spool['display_status']) ?>"><?= View::t('spool_status_'.$spool['display_status']) ?></span></td><td><?php if($spool['printer_name']): ?><?= View::e($spool['printer_name']) ?> · <?= View::t('slot') ?> <?= View::e($spool['slot_number']) ?><?php else: ?><?= View::e($location['name']) ?><?php endif; ?></td><td><?php if($canEditSpools): ?><a class="button secondary-button action-button" href="<?= View::e($basePath) ?>/spools/<?= View::e($spool['id']) ?>/edit"><?= View::t('edit') ?></a><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$spools): ?><tr><td colspan="7"><?= View::t('location_has_no_spools') ?></td></tr><?php endif; ?></tbody></table></div></section>
